Full script:

```js
(() => {
'use strict';
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const W = canvas.width;
const H = canvas.height;

const COLS = 10;
const ROW_HEIGHT = 26;
const BLOCK_GAP = 4;
const TOP_OFFSET = 70;

let level = 1;
let score = 0;
let lives = 3;
let highScore = Number(localStorage.getItem('breakout-highscore') || 0);

let state = 'ready'; // ready | playing | paused | levelclear | gameover
let stateTimer = 0;

const paddle = { w: 110, h: 14, x: W/2 - 55, speed: 520 };
const ball = { x: 0, y: 0, r: 8, vx: 0, vy: 0, stuck: true };

let blocks = [];

const keys = { left: false, right: false };

function ballSpeed() { return Math.min(340 + level * 30, 520); }

function buildLevel() {
  const rows = Math.min(4 + level, 8);
  const margin = 30;
  const blockW = (W - margin*2 - BLOCK_GAP*(COLS-1)) / COLS;
  blocks = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < COLS; c++) {
      const tough = level >= 2 && r < 2 && Math.random() < Math.min(0.15 + level*0.05, 0.5);
      blocks.push({
        x: margin + c*(blockW+BLOCK_GAP),
        y: TOP_OFFSET + r*(ROW_HEIGHT+BLOCK_GAP),
        w: blockW, h: ROW_HEIGHT,
        hp: tough ? 2 : 1,
        color: tough ? '#8a8f98' : `hsl(${(r*36+level*20)%360} 70% 55%)`
      });
    }
  }
  resetBall();
}

function resetBall() {
  ball.stuck = true;
  ball.vx = 0; ball.vy = 0;
  ball.x = paddle.x + paddle.w/2;
  ball.y = H - 40 - paddle.h - ball.r;
}

function launchBall() {
  if (!ball.stuck) return;
  const s = ballSpeed();
  const angle = (Math.random()*60 - 30) * Math.PI/180; // -30..30 from vertical
  ball.vx = s * Math.sin(angle);
  ball.vy = -s * Math.cos(angle);
  ball.stuck = false;
  state = 'playing';
}
```

